        function change(profit, trust, chaos) {
          const old = { ...meters };
          meters.profit = clamp(meters.profit + profit);
          meters.trust = clamp(meters.trust + trust);
          meters.chaos = clamp(meters.chaos + chaos);
          meterDelta = [
            meters.profit - old.profit,
            meters.trust - old.trust,
            meters.chaos - old.chaos,
          ];
          deltaUntil = time + 2.2;
          sfx(profit + trust - chaos < 0 ? "bad" : "meter");
        }
        function talk(
          speaker,
          pages,
          choices = null,
          after = null,
          back = null,
        ) {
          held = null;
          dialog = {
            speaker,
            pages: Array.isArray(pages) ? pages : [pages],
            page: 0,
            chars: 0,
            choices,
            index: 0,
            after,
            back,
            lastBlip: 0,
          };
          announce(
            speaker +
              ": " +
              dialog.pages[0] +
              (choices
                ? " Choices: " + choices.map((c) => c.label).join(", ")
                : ""),
          );
        }
        const choice = (label, effect, action) => ({ label, effect, action });
        function chooseDialog(dir) {
          const value = dialog.pages[dialog.page];
          if (dialog.chars < value.length) {
            dialog.chars = value.length;
            return;
          }
          if (dialog.page < dialog.pages.length - 1) {
            dialog.page++;
            dialog.chars = 0;
            announce(dialog.speaker + ": " + dialog.pages[dialog.page]);
            sfx("move");
            return;
          }
          if (dialog.choices) {
            if (dir === "up" || dir === "down") {
              dialog.index =
                (dialog.index +
                  (dir === "up" ? -1 : 1) +
                  dialog.choices.length) %
                dialog.choices.length;
              sfx("move");
              return;
            }
            if (dir === "left") {
              if (dialog.back) {
                const fn = dialog.back;
                dialog = null;
                fn();
              } else {
                dialog.page = 0;
                dialog.chars = 0;
              }
              return;
            }
            if (dir !== "right") return;
            const selected = dialog.choices[dialog.index];
            dialog = null;
            sfx("select");
            if (selected.effect) change(...selected.effect);
            selected.action();
          } else {
            const next = dialog.after;
            dialog = null;
            sfx("move");
            if (next) next();
          }
        }
