                ? 'It plays one note. Ruth calls it "ambient."'
                : "NOW PLAYING: Girls Just Wanna Have A Sustainable Business Model.",
            );
            return;
          }
          talk("CO-OP BULLETIN BOARD", [
            "LOST: one sense of proportion. FOUND: fourteen reusable water bottles.",
            "COMMUNITY REMINDER: All characters, accounts, and names in this game are fictional. Kindness is not.",
          ]);
        }
        function move(dir) {
          const dirs = {
            up: [0, -1],
            down: [0, 1],
            left: [-1, 0],
            right: [1, 0],
          };
          player.dir = dir;
          const [dx, dy] = dirs[dir];
          const x = player.x + dx,
            y = player.y + dy;
          if (screen === "world") {
            const object = storyObjects().find((o) => o.x === x && o.y === y);
            if (object) {
              bumpObject(object.id);
              return;
            }
            if (x < 1 || x > 20 || y < 1 || y > 8) return;
            if (world === "bar" && y === 1 && x >= 6 && x <= 14) return;
          } else {
            if (x < 1 || x > 20 || y < 2 || y > 8) {
              const station = STATIONS.find((o) => o.x === x && o.y === y);
              if (station) useStation(station);
              return;
            }
            const station = STATIONS.find((o) => o.x === x && o.y === y);
            if (station) {
              useStation(station);
              return;
            }
            const patron = arcade.patrons.find((o) => o.x === x && o.y === y);
            if (patron) {
              serve(patron);
              return;
            }
            const visitor = arcade.visitors.find((o) => o.x === x && o.y === y);
            if (visitor) {
              notify(
                visitor.kind === "care"
                  ? "CONCERNED NEIGHBORS: TRY SNACKS OR APOLOGY."
                  : visitor.kind === "petition"
                    ? "PETITIONERS: TRY CHALK OR APOLOGY."
                    : "CONFUSED CLOWNS: TRY DANCE OR SNACKS.",
              );
              return;
            }
          }
          player.x = x;
          player.y = y;
        }

        function startArcade() {
          setScreen("arcade");
          setTheme("boss");
          player = { x: 10, y: 5, dir: "up" };
          const base = MASKS[mask.base];
          change(
            base.id === "novelty" ? 3 : 0,
            base.id === "cloth" ? 10 : base.id === "n95" ? 4 : 0,
            base.id === "n95" ? -3 : 0,
          );
          arcade = {
            elapsed: 0,
            points: 0,
            vibe: base.id === "novelty" ? 90 : 60,
            stamina: base.stamina,
            patrons: [],
            visitors: [],
            spawned: 0,
            waves: 0,
            served: 0,
            cooldowns: {},
            sickDays: 0,
            drainAt: 5,
            slowUntil: 0,
          };
          spawnPatron();
          notify("DOORS OPEN! BUMP PATRONS TO SERVE. KEEP THE VIBE UP.");
        }
        const SEATS = [
          [4, 3],
          [8, 3],
          [12, 3],
          [16, 3],
          [5, 5],
          [9, 5],
          [13, 5],
          [17, 5],
        ];
        function spawnPatron() {
          arcade.spawned++;
          const free = SEATS.filter(
            ([x, y]) =>
              !arcade.patrons.some((p) => p.x === x && p.y === y) &&
              !(player.x === x && player.y === y),
          );
          if (!free.length) return;
          const [x, y] = free[Math.floor(Math.random() * free.length)];
          const patience = 15 + meters.trust / 12;
          arcade.patrons.push({
            id: arcade.spawned,
            x,
            y,
            patience,
            max: patience,
            color: [C.pink, C.mint, C.blue, C.orange][arcade.spawned % 4],
          });
        }
        function addPoints(amount) {
          arcade.points = Math.min(7500, arcade.points + amount);
        }
        function serve(patron) {
          addPoints(100 + Math.floor((50 * patron.patience) / patron.max));
          arcade.served++;
          arcade.patrons = arcade.patrons.filter((p) => p !== patron);
          change(2, 1, -1);
          arcade.vibe = clamp(arcade.vibe + 3);
          sfx("serve");
          if (arcade.served % 5 === 0) {
            sfx("level");
            notify(
              arcade.served + " SERVED! THE REGULARS ARE ROOTING FOR YOU.",
            );
          }
        }
        function spawnWave() {
          const kind = ["care", "petition", "clown"][arcade.waves % 3];
          arcade.waves++;
          const friendly = factions[kind] >= (kind === "petition" ? 1 : 2);
          if (friendly) {
            addPoints(250);
            change(2, 3, -4);
            arcade.vibe = clamp(arcade.vibe + 12);
            if (arcade.patrons[0]) serve(arcade.patrons[0]);
            notify(
              kind === "care"
                ? "ALLY WAVE: WILLOW BRINGS SNACKS AND AN EXTRA PAIR OF HANDS."
                : kind === "petition"
                  ? "ALLY WAVE: THE COMMITTEE ORGANIZES THE DRINK QUEUE."
                  : "ALLY WAVE: CLOWN VOLUNTEERS NAIL THE LINE DANCE.",
            );
            return;
          }
          const x = arcade.waves % 2 ? 2 : 19;
          arcade.visitors.push({
            kind,
            x,
            y: 4,
            patience: 14,
            id: arcade.waves,
          });
          change(0, -2, 5);
          notify(
            kind === "care"
              ? "NEIGHBORS HAVE QUESTIONS. SNACKS OR AN APOLOGY HELP."
              : kind === "petition"
                ? "PETITION WAVE! TRY THE CHALKBOARD OR APOLOGY STATION."
                : "CLOWN WAVE! WRONG ADDRESS. TRY SNACKS OR A LINE DANCE.",
          );
        }
        function useStation(station) {
          if ((arcade.cooldowns[station.id] || 0) > arcade.elapsed) {
            notify(
              station.label +
                " RECHARGING. " +
                Math.ceil(arcade.cooldowns[station.id] - arcade.elapsed) +
                " SECONDS.",
            );
            return;
          }
          arcade.cooldowns[station.id] =
            arcade.elapsed +
            (["dj", "lights", "karaoke"].includes(station.id) ? 5 : 8);
          const boosts = {
            dj: 24,
            lights: 18,
            karaoke: 28,
            snacks: 8,
            apology: 6,
            chalk: 4,
            dance: 22,
          };
          arcade.vibe = clamp(
            arcade.vibe + boosts[station.id] + (mask.base === 2 ? 8 : 0),
          );
          const matches = {
            snacks: ["care", "clown"],
            apology: ["care", "petition"],
            chalk: ["petition"],
            dance: ["clown"],
          };
          const resolved = arcade.visitors.filter((v) =>
            (matches[station.id] || []).includes(v.kind),
          );
          for (const visitor of resolved) {
            arcade.visitors = arcade.visitors.filter((v) => v !== visitor);
            addPoints(250);
          }
          change(
            station.id === "snacks" ? -2 : 1,
            resolved.length ? 4 : 1,
            resolved.length ? -8 : -1,
          );
          sfx("select");
          notify(
            {
              dj: "DJ: FLANNEL BANGERS, VOLUME TWO.",
              lights: "STRING LIGHTS: COZY LEVEL RESTORED.",
              karaoke: "KARAOKE: EVERYONE KNOWS THE CHORUS.",
              snacks: "FREE SNACKS. NO MEETING REQUIRED.",
              apology: '"I HEAR YOU. HERE IS WHAT WE CAN DO."',
              chalk: "A CLEAR PLAN. LEGIBLE HANDWRITING. RADICAL.",
              dance: "STEP LEFT. STEP RIGHT. COLLECTIVE EXHALE.",
            }[station.id] +
              (resolved.length ? " +" + resolved.length * 250 : ""),
          );
        }
        function updateArcade(dt) {
          arcade.elapsed += dt;
          arcade.vibe = clamp(arcade.vibe - dt * 2.4);
          if (arcade.spawned < 30 && arcade.elapsed >= arcade.spawned * 2.8)
            spawnPatron();
          if (arcade.waves < 6 && arcade.elapsed >= 10 + arcade.waves * 13)
            spawnWave();
          for (const p of [...arcade.patrons]) {
            p.patience -= dt * (arcade.vibe < 25 ? 1.5 : 1);
            if (p.patience <= 0) {
              arcade.patrons = arcade.patrons.filter((item) => item !== p);
              change(-3, -2, 3);
              notify("A PATRON HEADS HOME. TOMORROW IS ANOTHER NIGHT.");
            }
          }
          for (const v of [...arcade.visitors]) {
            v.patience -= dt;
            if (v.patience <= 0) {
              arcade.visitors = arcade.visitors.filter((item) => item !== v);
              change(-3, -3, 6);
              notify("THE VISITORS LEAVE WITH UNRESOLVED AGENDA ITEMS.");
            }

