function updateArcade(dt) {
  arcade.elapsed += dt;
  arcade.vibe = clamp(arcade.vibe - dt * 2.4);
  if (arcade.spawned < 30 && arcade.elapsed >= arcade.spawned * 2.8)
    spawnPatron();
  if (arcade.waves < 6 && arcade.elapsed >= 10 + arcade.waves * 13)
    spawnWave();
  for (const p of [...arcade.patrons]) {
    p.patience -= dt * (arcade.vibe < 25 ? 1.5 : 1);
    if (p.patience <= 0) {
      arcade.patrons = arcade.patrons.filter((item) => item !== p);
      change(-3, -2, 3);
      notify("A PATRON HEADS HOME. TOMORROW IS ANOTHER NIGHT.");
    }
  }
  for (const v of [...arcade.visitors]) {
    v.patience -= dt;
    if (v.patience <= 0) {
      arcade.visitors = arcade.visitors.filter((item) => item !== v);
      change(-3, -3, 6);
      notify("THE VISITORS LEAVE WITH UNRESOLVED AGENDA ITEMS.");
    }
  }
  if (
    arcade.elapsed >= 28 + arcade.sickDays * 30 &&
    arcade.sickDays < 2
  ) {
    arcade.sickDays++;
    const protectedShift = arcade.stamina > 0;
    if (protectedShift) arcade.stamina--;
    change(mask.base === 0 ? -2 : -6, 0, protectedShift ? 2 : 7);
    arcade.slowUntil = arcade.elapsed + (protectedShift ? 1 : 5);
    notify(
      mask.base === 0
        ? "STAFF SICK DAY. YOUR N95 STAMINA SOFTENS THE SHIFT PENALTY."
        : "STAFF SICK DAY. COVERING THE SHIFT COSTS " +
            (protectedShift
              ? "ONE STAMINA."
              : "ENERGY. TAKE IT STEADY."),
    );
  }
  if (arcade.elapsed >= arcade.drainAt) {
    arcade.drainAt += 5;
    if (arcade.vibe < 25) change(-2, -1, 2);
  }
  if (arcade.elapsed >= 90) {
