+import { test, expect } from '@playwright/test';
+import { readFile } from 'node:fs/promises';
+import { runInNewContext } from 'node:vm';
+import { randomUUID } from 'node:crypto';
+
+async function model() {
+  const html = await readFile(new URL('../public/index.html', import.meta.url), 'utf8');
+  const source = html.match(/<script>([\s\S]*?)<\/script>/)[1];
+  const element = { dataset: {}, getContext: () => ({}), setAttribute() {}, addEventListener() {} };
+  const sandbox = {
+    document: { getElementById: () => element, querySelectorAll: () => [], addEventListener() {} },
+    window: { addEventListener() {} }, matchMedia: () => ({ matches: false }),
+    localStorage: { getItem: () => null }, requestAnimationFrame() {},
+    performance: { now: () => 0 }, crypto: { randomUUID },
+  };
+  const insertion = `globalThis.game = {
+    resetGame, startArcade, updateArcade, useStation, spawnWave, serve, pickEnding, finishArcade, input,
+    state: () => ({ meters, factions, mask, arcade, score, ending, player, screen, dialog, shown, policy }),
+    setup: (values) => {
+      if (values.meters) meters = values.meters;
+      if (values.factions) factions = values.factions;
+      if (values.mask) mask = values.mask;
+      if (values.player) player = values.player;
+      if (values.screen) screen = values.screen;
+      if (values.clearDialog) dialog = null;
+    },
+    stations: STATIONS, masks: MASKS, maxScore: 10500
+  };`;
+  const closing = source.lastIndexOf('})();');
+  runInNewContext(source.slice(0, closing) + insertion + source.slice(closing), sandbox);
+  return sandbox.game;
+}
+
+test('all four warm endings are reachable from final meters and choices', async () => {
+  const game = await model();
+  const cases = [
+    [{ profit: 60, trust: 80, chaos: 20 }, { care: 3, clown: 0, petition: 0 }, 'compromise'],
+    [{ profit: 45, trust: 50, chaos: 55 }, { care: 0, clown: 3, petition: 0 }, 'clown'],
+    [{ profit: 50, trust: 40, chaos: 80 }, { care: 0, clown: 0, petition: 0 }, 'viral'],
+    [{ profit: 30, trust: 55, chaos: 45 }, { care: 0, clown: 0, petition: 0 }, 'committee'],
+  ];
+  for (const [meters, factions, expected] of cases) {
+    game.setup({ meters, factions });
+    expect(game.pickEnding()).toBe(expected);
+  }
+});
+
+test('masks have distinct stamina, trust, vibe, and sick-day effects', async () => {
+  const snapshots = [];
+  for (let base = 0; base < 4; base++) {
+    const game = await model();
+    game.resetGame();
+    game.setup({ mask: { base, color: 0, pattern: 0, accessory: 3 }, clearDialog: true });
+    game.startArcade();
+    const state = game.state();
+    snapshots.push({ stamina: state.arcade.stamina, trust: state.meters.trust, vibe: state.arcade.vibe });
+    state.arcade.elapsed = 27.99;
+    state.arcade.spawned = 30;
+    state.arcade.waves = 6;
+    state.arcade.patrons = [];
+    game.updateArcade(.02);
+    snapshots[base].profit = state.meters.profit;
+  }
