              const before = Math.floor(dialog.chars);
              dialog.chars = Math.min(
                dialog.pages[dialog.page].length,
                dialog.chars + dt * (reduced ? 150 : 44),
              );
              if (
                Math.floor(dialog.chars) !== before &&
                time - dialog.lastBlip > 0.065
              ) {
                dialog.lastBlip = time;
                sfx("blip");
              }
            }
            if (
              held &&
              now >= repeatAt &&
              !dialog &&
              (screen === "world" || screen === "arcade")
            ) {
              input(held);
              repeatAt =
                now +
                (screen === "arcade"
                  ? (mask.base === 3 ? 110 : 135) +
                    (arcade.slowUntil > arcade.elapsed ? 55 : 0)
                  : 135);
            }
            if (screen === "arcade") updateArcade(dt);
            if (screen === "tally") {
              const previous = Math.floor(tallyAge * 8);
              tallyAge += dt;
              if (tallyAge < 3.2 && Math.floor(tallyAge * 8) !== previous)
                tone(65, 0.035, 0.022);
            }
            music();
          }
          render();
          requestAnimationFrame(frame);
        }
        setScreen("title");
        requestAnimationFrame(frame);
      })();
    </script>
  </body>
</html>
